// Test-only lower native material model. Original source paths remain unchanged.
function lowerNativeComposite(c,cv,q){
 const m=c.getTransform(),w=cv.width,h=cv.height,split=Math.max(0,Math.min(h,Math.floor(m.d*1716+m.f))),y0=split,y1=Math.min(h,Math.ceil(m.d*1988.8+m.f)+2),rows=y1-y0;
 if(rows<=0)return;
 const mask=transitionColor,work=transitionWork;resizeTransition(mask,w,rows);resizeTransition(work,w,rows);
 const mc=mask.getContext('2d');mc.setTransform(1,0,0,1,0,0);mc.globalAlpha=1;mc.globalCompositeOperation='source-over';mc.clearRect(0,0,w,rows);
 mc.setTransform(m.a,m.b,m.c,m.d,m.e,m.f-y0);mc.save();mc.clip(q.apron);mc.scale(2.2,2.2);
 // Original paint order, including later gray and topmost roads. This alpha
